//! Mystic quests (rules 0.9.0, DM_RULEBOOK chapter 27): the Lens and the Engine as a thing the player can DO.
//!
//! A quest is a short chain (1-3 steps) of concrete requirements the engine can verify from the state, generated by
//! RULES from seeded tables and the place × time memory ([`give`]), then phrased in Rube Goldberg mystical style
//! ("the wings of a butterfly that has crossed the Sunda Strait, burned at dawn on the shrine of the one who cursed
//! you"). Quests are stored (`Book::quests`), progress each beat from what actually happened ([`step`]: where the
//! demigods stand, what they hold, the encounters they won, the shrines they raised, the duels they survived, the
//! sparks they offered), are remembered in the DM's memory (`quest.given`, `quest.step`, `quest.done`,
//! `quest.failed`), expire or stay, and on completion apply their effect: the heal completes, the gear is tempered,
//! the curse breaks, the demigod rises.

use fn7_model::dm::Scope;
use fn7_model::hexgrid::HexLevel;
use fn7_model::manifest::{ItemEvent, ItemKind, ItemState, Tier};
use fn7_model::seed::Rng;
use fn7_model::*;
use fn7_society::geo::{destination, distance_km, on_land};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use super::curses::CurseKind;
use super::Book;
use crate::dm::{self, Decision};
use crate::settings::Settings;
use crate::world::event;

const QUEST_SALT: u64 = 0x9E57;

/// The odd ingredients: (what the DM calls it, the word an item's name must carry).
pub const INGREDIENTS: &[(&str, &str)] = &[
    ("the wings of a butterfly that has crossed the {strait}", "butterfly"),
    ("a stone washed in platinum dust", "platinum"),
    ("a heron's feather that never touched water", "feather"),
    ("salt from a sea that dried before the first war", "salt"),
    ("a candle of whale tallow lit from another candle", "candle"),
    ("the ash of an oak struck twice by lightning", "ash"),
    ("a jar of fog bottled before sunrise", "fog"),
    ("a bell without a tongue", "bell"),
    ("river glass worn round by a single flood", "glass"),
    ("a thread pulled from a general's banner", "thread"),
];
const STRAITS: &[&str] = &["Sunda Strait", "Bosphorus", "Strait of Gibraltar", "Bering Strait", "Strait of Hormuz", "Palk Strait"];

/// How near "at" is (km), on the planet: within this of the place (a city arena uses a hundredth).
pub const AT_KM: f64 = 150.0;
/// "Near a fault line" and "on a coast" (km).
pub const FAULT_KM: f64 = 150.0;
pub const COAST_KM: f64 = 80.0;
/// An army "reaches" a place within this (km).
pub const ARMY_KM: f64 = 300.0;

/// What finishing the quest does.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "kind")]
pub enum Goal {
    /// The rest of a heal that fell short.
    Heal { amount: f32 },
    /// A blessing that fell short: a boon of `bonus` for `beats` beats.
    Boon { bonus: i32, beats: u32 },
    /// Gear that came out a tier low is tempered up to `tier`.
    Temper { item: Option<ItemId>, intent: u32, tier: Tier },
    /// Gear that did not appear at all: it is forged at the end.
    Arm { slot: String, tier: Tier, name: String, god: Option<GodId> },
    /// The curse breaks.
    BreakCurse { curse: u32, curse_kind: CurseKind },
    /// The fallen demigod rises (for `years` of its max health).
    Raise { years: f32 },
}

impl Goal {
    pub fn kind(&self) -> &'static str {
        match self {
            Goal::Heal { .. } => "heal",
            Goal::Boon { .. } => "boon",
            Goal::Temper { .. } => "temper",
            Goal::Arm { .. } => "arm",
            Goal::BreakCurse { .. } => "break_curse",
            Goal::Raise { .. } => "raise",
        }
    }
}

/// A kind of place a step asks for.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "place")]
pub enum PlaceReq {
    /// A shrine of this demigod (the one who cursed you, or one of your own).
    Shrine { of: DemigodId },
    /// Any settlement of this level or more.
    Settlement { level: u8 },
    /// Within [`FAULT_KM`] of a fault line.
    Fault,
    /// On a coast.
    Coast,
    /// A remembered spot.
    Point { at: LonLat, name: String },
}

/// One checkable requirement.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case", tag = "kind")]
pub enum StepKind {
    /// Stand at a place (or a kind of place), at a time of day if `phase` is set; with `offer`, an item whose name
    /// carries that word must be in hand there, and it is burned (destroyed) as the step completes.
    At {
        #[serde(flatten)]
        req: PlaceReq,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        phase: Option<String>,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        offer: Option<String>,
    },
    /// Hold an item whose name carries `word` (the item engine can make it, a won encounter drops it, loot may hold it).
    Hold { word: String },
    /// Win an encounter (a success or better on a marked hex).
    Encounter,
    /// Raise a shrine.
    Shrine,
    /// Come out of a duel alive.
    Duel,
    /// Offer sparks (a will: "offer the sparks").
    Sparks { n: u32 },
    /// One of your armies (its general named in the telling) stands within [`ARMY_KM`] of the place.
    Army { at: LonLat, name: String, general: String },
    /// Keep vigil: wait until that time of day has come `times` times (`seen` so far).
    Vigil {
        phase: String,
        #[serde(default = "one")]
        times: u32,
        #[serde(default)]
        seen: u32,
    },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Step {
    #[serde(flatten)]
    pub kind: StepKind,
    /// The requirement in plain words.
    pub text: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub done_beat: Option<u32>,
    /// Why it is not done yet, as of the last check ("you stand there, but it is not dawn").
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub progress: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Quest {
    pub id: u32,
    /// Whose quest it is (they see the steps; their standing demigods do them).
    pub seat: u8,
    /// Other players who took it up (a plea for someone else's fallen demigod).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub helpers: Vec<u8>,
    /// Whom it is for (the one healed, armed, cursed or raised).
    pub demigod: DemigodId,
    pub goal: Goal,
    /// The god whose ruling it is.
    pub god: GodId,
    pub steps: Vec<Step>,
    /// The DM's telling (Rube Goldberg mystical).
    pub text: String,
    pub given_beat: u32,
    /// Events count from this beat on (the beat after the previous step was done).
    pub since: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub expires_beat: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub done_beat: Option<u32>,
    /// `expired` | `moot` (what it was for no longer applies).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub failed: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub failed_beat: Option<u32>,
    /// Everyone sees it (a raising, a seal's counter); else only its seat (and a curse's owner).
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub public: bool,
    /// Every step is done but something still holds its effect back (a seal on the one to be raised).
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub waiting: String,
}

impl Quest {
    pub fn open(&self) -> bool {
        self.done_beat.is_none() && self.failed.is_none()
    }
    pub fn status(&self) -> &'static str {
        match (&self.done_beat, &self.failed) {
            (Some(_), _) => "done",
            (None, Some(_)) => "failed",
            _ => "open",
        }
    }
    /// The first step not yet done.
    pub fn current(&self) -> Option<usize> {
        self.steps.iter().position(|s| s.done_beat.is_none())
    }
    pub fn takes(&self, seat: u8) -> bool {
        self.seat == seat || self.helpers.contains(&seat)
    }
}

fn one() -> u32 {
    1
}

pub fn qref(id: u32) -> String {
    format!("q:{id}")
}

fn scale(w: &World) -> f64 {
    if w.is_planet() {
        1.0
    } else {
        0.01
    }
}

/// Is `pos` on a coast: land with sea within [`COAST_KM`], or sea with land that near.
pub fn is_coast(w: &World, pos: LonLat) -> bool {
    let here = on_land(pos);
    let km = COAST_KM * scale(w);
    (0..8).any(|k| on_land(destination(pos, k as f64 * 45.0, km)) != here)
}

/// Does `pos` satisfy `req`?
pub fn place_ok(w: &World, req: &PlaceReq, pos: LonLat) -> bool {
    let at = AT_KM * scale(w);
    match req {
        PlaceReq::Shrine { of } => w.dm.shrines.iter().any(|s| s.demigod == *of && distance_km(s.at, pos) <= at),
        PlaceReq::Settlement { level } => {
            dm::settlement_at(w, pos).and_then(|p| w.dm.settlement(p)).is_some_and(|s| s.level >= *level)
        }
        PlaceReq::Fault => crate::faults::index().distance_km(pos, FAULT_KM * 2.0) <= FAULT_KM,
        PlaceReq::Coast => is_coast(w, pos),
        PlaceReq::Point { at: p, .. } => distance_km(*p, pos) <= at,
    }
}

fn place_words(w: &World, req: &PlaceReq, me: DemigodId) -> (String, String) {
    match req {
        PlaceReq::Shrine { of } if w.same_player(*of, me) => ("at one of your own shrines".into(), "on your own shrine".into()),
        PlaceReq::Shrine { of } => (
            format!("at a shrine of {}", w.name_of(Ref::Demigod(*of))),
            "on the shrine of the one who cursed you".into(),
        ),
        PlaceReq::Settlement { level } => {
            let n = ["a hamlet", "a hamlet", "a village", "a town", "a city", "a great city", "a legendary city", "a legendary city"][(*level).min(7) as usize];
            (format!("in a settlement of level {level} or more ({n})"), format!("in the square of {n} that has outgrown its walls"))
        }
        PlaceReq::Fault => (
            format!("within {FAULT_KM:.0} km of a fault line"),
            "where the ground remembers being two grounds".into(),
        ),
        PlaceReq::Coast => ("on a coast".into(), "where the land gives up and the sea begins".into()),
        PlaceReq::Point { name, .. } => (format!("at {name}"), format!("at {name}, where the DM has already written something down")),
    }
}

fn phase_words(p: &str) -> &'static str {
    match p {
        "dawn" => "at dawn",
        "dusk" => "at dusk",
        "night" => "by night",
        _ => "in full daylight",
    }
}

/// Everything [`give`] needs to know about a new quest.
pub struct Ask {
    pub seat: u8,
    pub demigod: DemigodId,
    pub goal: Goal,
    pub god: GodId,
    /// 1..3: its length.
    pub difficulty: u8,
    /// The one who cursed (for "the shrine of the one who cursed you").
    pub curser: Option<DemigodId>,
    pub public: bool,
    pub expires_beat: Option<u32>,
}

/// Generate a quest by rules (seeded by the match and the quest's id), store it and remember it (`quest.given`).
pub fn give(w: &mut World, book: &mut Book, beat: u32, a: Ask, st: &Settings) -> u32 {
    let id = book.quests.len() as u32;
    let mut rng = Rng::derive(w.meta.seed, &[QUEST_SALT, id as u64, beat as u64]);
    let standing: Vec<DemigodId> = w.bodies_of_seat(a.seat).filter(|d| d.alive).map(|d| d.id).collect();
    let anchor = standing.first().map(|d| w.demigods[d.ix()].pos).unwrap_or(w.demigods[a.demigod.ix()].pos);
    let n = (a.difficulty.clamp(1, 3) as usize).min(st.quest_steps_max.clamp(1, 3) as usize);
    // The pool: what this seat can actually do now.
    #[derive(Clone, Copy, PartialEq)]
    enum K {
        Hold,
        At,
        Encounter,
        Shrine,
        Duel,
        Sparks,
        Army,
        Vigil,
    }
    let army = w
        .bodies_of_seat(a.seat)
        .filter_map(|d| crate::beat::own_army(w, d.id))
        .find_map(|c| {
            let cl = &w.clusters[c.ix()];
            let g = cl.army.as_ref()?.general.filter(|g| w.characters[g.ix()].alive)?;
            Some((cl.label.clone(), w.characters[g.ix()].name.clone()))
        });
    let mut pool: Vec<(K, u32)> = vec![];
    if standing.is_empty() {
        // The fallen can't walk: a vigil, and an offering when the purse could make it.
        pool.push((K::Vigil, 3));
        let me = &w.demigods[a.demigod.ix()];
        let purse = w.bodies_of_seat(a.seat).next().map(|d| d.sparks + d.bolts * st.will_spark_per_bolt).unwrap_or(me.sparks);
        if purse >= (st.quest_spark_step * a.difficulty.clamp(1, 3) as u32).max(1) {
            pool.push((K::Sparks, 3));
        }
    } else {
        pool.extend([(K::Hold, 4), (K::At, 6), (K::Sparks, 2), (K::Vigil, 2)]);
        if st.dm_encounters_per_beat > 0 && st.dm_encounters_max > 0 {
            pool.push((K::Encounter, 2));
        }
        let shrines = w.dm.shrines.iter().filter(|s| standing.contains(&s.demigod)).count() as u32;
        if shrines < st.dm_shrines_per_demigod * standing.len() as u32 {
            pool.push((K::Shrine, 2));
        }
        if st.challenge_enabled && a.difficulty >= 3 {
            pool.push((K::Duel, 1));
        }
        if army.is_some() {
            pool.push((K::Army, 2));
        }
    }
    let mut kinds: Vec<K> = vec![];
    while kinds.len() < n && !pool.is_empty() {
        let total: u32 = pool.iter().map(|x| x.1).sum();
        let mut r = rng.below(total as u64) as u32;
        let mut ix = 0;
        for (i, x) in pool.iter().enumerate() {
            if r < x.1 {
                ix = i;
                break;
            }
            r -= x.1;
        }
        kinds.push(pool.remove(ix).0);
    }
    // A telling reads best in this order: get the thing, do the deed, go to the place, wait.
    let order = |k: &K| match k {
        K::Hold => 0,
        K::Sparks => 1,
        K::Encounter | K::Shrine | K::Duel => 2,
        K::Army => 3,
        K::At => 4,
        K::Vigil => 5,
    };
    kinds.sort_by_key(order);
    let phases = ["dawn", "dusk", "night", "day"];
    // An ingredient nobody of theirs holds yet.
    let unheld: Vec<(&str, &str)> = INGREDIENTS.iter().copied().filter(|(_, word)| !standing.iter().any(|d| held_with(w, *d, word).is_some())).collect();
    let pool_ing: &[(&str, &str)] = if unheld.is_empty() { INGREDIENTS } else { &unheld };
    let (ing_phrase, ing_word) = *rng.pick(pool_ing).unwrap_or(&INGREDIENTS[0]);
    let ing_phrase = ing_phrase.replace("{strait}", rng.pick(STRAITS).copied().unwrap_or("Sunda Strait"));
    let has_hold = kinds.contains(&K::Hold);
    let mut steps = vec![];
    let mut frags: Vec<String> = vec![];
    for k in &kinds {
        match k {
            K::Hold => {
                steps.push(Step {
                    kind: StepKind::Hold { word: ing_word.into() },
                    text: format!("Hold {ing_phrase} (any item with \"{ing_word}\" in its name: will your demigod to gather or make it, or win an encounter)."),
                    done_beat: None,
                    progress: String::new(),
                });
                frags.push(ing_phrase.clone());
            }
            K::At => {
                let req = place_req(w, &mut rng, &a, &standing, anchor, beat);
                let phase = (rng.below(2) == 0).then(|| phases[rng.below(4) as usize].to_string());
                let offer = (has_hold && rng.below(3) != 0).then(|| ing_word.to_string());
                let (plain, mystic) = place_words(w, &req, a.demigod);
                let when = phase.as_deref().map(phase_words);
                let text = match (&offer, when) {
                    (Some(o), Some(t)) => format!("Stand {plain} {t} with the {o} item in hand: it is burned there."),
                    (Some(o), None) => format!("Stand {plain} with the {o} item in hand: it is burned there."),
                    (None, Some(t)) => format!("Stand {plain} {t}."),
                    (None, None) => format!("Stand {plain}."),
                };
                frags.push(match (&offer, when) {
                    (Some(_), Some(t)) => format!("burned {t} {mystic}"),
                    (Some(_), None) => format!("burned {mystic}"),
                    (None, Some(t)) => format!("your shadow laid down {t} {mystic}"),
                    (None, None) => format!("your shadow laid down {mystic}"),
                });
                steps.push(Step { kind: StepKind::At { req, phase, offer }, text, done_beat: None, progress: String::new() });
            }
            K::Encounter => {
                steps.push(Step { kind: StepKind::Encounter, text: "Win an encounter on a marked hex (a success or better).".into(), done_beat: None, progress: String::new() });
                frags.push("the thing that waits on a marked hex bested and thanked".into());
            }
            K::Shrine => {
                steps.push(Step { kind: StepKind::Shrine, text: "Raise a new shrine (will it: \"raise a shrine to me here\").".into(), done_beat: None, progress: String::new() });
                frags.push("a new shrine raised by the hands that ask".into());
            }
            K::Duel => {
                steps.push(Step { kind: StepKind::Duel, text: "Come out of a duel alive.".into(), done_beat: None, progress: String::new() });
                frags.push("a duel walked away from on both feet".into());
            }
            K::Sparks => {
                let nsp = (st.quest_spark_step * a.difficulty.clamp(1, 3) as u32).max(1);
                steps.push(Step {
                    kind: StepKind::Sparks { n: nsp },
                    text: format!("Offer {nsp} spark{} (will it: \"offer the sparks to the quest\"; a bolt breaks into {}).", if nsp == 1 { "" } else { "s" }, st.will_spark_per_bolt),
                    done_beat: None,
                    progress: String::new(),
                });
                frags.push(format!("{nsp} spark{} fed to the dark between two heartbeats", if nsp == 1 { "" } else { "s" }));
            }
            K::Army => {
                let (label, general) = army.clone().unwrap_or_default();
                let req = place_req(w, &mut rng, &a, &standing, anchor, beat);
                let (at, name) = match &req {
                    PlaceReq::Point { at, name } => (*at, name.clone()),
                    _ => nearest_settlement(w, anchor, 1).unwrap_or((anchor, "where you stand".into())),
                };
                let surname = general.rsplit(' ').next().unwrap_or(&general).to_string();
                steps.push(Step {
                    kind: StepKind::Army { at, name: name.clone(), general: general.clone() },
                    text: format!("Have General {surname} bring {label} within {ARMY_KM:.0} km of {name}."),
                    done_beat: None,
                    progress: String::new(),
                });
                frags.push(format!("General {surname}'s banners planted in sight of {name}"));
            }
            K::Vigil => {
                let phase = phases[rng.below(3) as usize].to_string();
                // The fallen keep longer vigils (it is all they can do): one coming of the hour per point of difficulty.
                let times = if standing.is_empty() { a.difficulty.clamp(1, 3) as u32 } else { 1 };
                steps.push(Step {
                    kind: StepKind::Vigil { phase: phase.clone(), times, seen: 0 },
                    text: if times == 1 { format!("Wait for the next {phase}.") } else { format!("Keep vigil until {phase} has come {times} times.") },
                    done_beat: None,
                    progress: String::new(),
                });
                frags.push(if times == 1 { format!("and then nothing at all until the next {phase}") } else { format!("and then nothing at all while {phase} comes {times} times") });
            }
        }
    }
    let god = w.name_of(Ref::God(a.god));
    let who = w.name_of(Ref::Demigod(a.demigod));
    let end = match &a.goal {
        Goal::Heal { .. } => format!("only then will the rest of {who}'s mending hold"),
        Goal::Boon { .. } => format!("only then will the blessing settle on {who}"),
        Goal::Temper { .. } => format!("only then will {who}'s gear take its true temper"),
        Goal::Arm { name, .. } => format!("only then will the {name} consent to exist"),
        Goal::BreakCurse { curse_kind, .. } => format!("only then will {} lift from {who}", curse_kind.title().trim_start_matches("a ")),
        Goal::Raise { .. } => format!("only then will {who} get up"),
    };
    // The lens: a settled fact about the place, when the memory holds one.
    let region = fn7_society::geo::region_at(w, anchor);
    let lens = dm::prompt_lines(w, region, beat.saturating_sub(1), 3).into_iter().last().map(|l| {
        let l = l.split_once(": ").map(|x| x.1.to_string()).unwrap_or(l);
        format!(" (The engine's reason, as near as the DM can read it: {})", l.trim_end_matches('.'))
    });
    let text = format!("{god} has ruled: {}; {end}.{}", frags.join(", then "), lens.unwrap_or_default());
    let q = Quest {
        id,
        seat: a.seat,
        helpers: vec![],
        demigod: a.demigod,
        goal: a.goal,
        god: a.god,
        steps,
        text,
        given_beat: beat,
        since: beat,
        expires_beat: a.expires_beat,
        done_beat: None,
        failed: None,
        failed_beat: None,
        public: a.public,
        waiting: String::new(),
    };
    event("quest_given", Some(format!("seat:{}", q.seat)), json!({ "beat": beat, "quest": q }));
    note(w, beat, &q, "quest.given", format!("A mystic quest is laid on {who}: {}", q.text), json!({ "steps": steps_json(&q) }));
    book.quests.push(q);
    id
}

fn nearest_settlement(w: &World, from: LonLat, min_level: u8) -> Option<(LonLat, String)> {
    w.dm
        .settlements
        .iter()
        .filter(|s| s.level >= min_level)
        .map(|s| (distance_km(w.places[s.place.ix()].center, from), s))
        .min_by(|a, b| a.0.total_cmp(&b.0).then(a.1.place.cmp(&b.1.place)))
        .map(|(_, s)| (w.places[s.place.ix()].center, w.places[s.place.ix()].name.clone()))
}

/// Pick a place requirement the seat can reach: the curser's shrine, its own shrine, a settlement of a level that
/// exists, a fault line, a coast, or a spot the DM's memory holds something about.
fn place_req(w: &World, rng: &mut Rng, a: &Ask, standing: &[DemigodId], anchor: LonLat, beat: u32) -> PlaceReq {
    let mut opts: Vec<(PlaceReq, u32)> = vec![(PlaceReq::Fault, 2), (PlaceReq::Coast, 2)];
    if let Some(c) = a.curser.filter(|c| w.dm.shrines.iter().any(|s| s.demigod == *c)) {
        opts.push((PlaceReq::Shrine { of: c }, 6));
    }
    if let Some(s) = w.dm.shrines.iter().find(|s| standing.contains(&s.demigod)) {
        opts.push((PlaceReq::Shrine { of: s.demigod }, 3));
    }
    let top = w.dm.settlements.iter().map(|s| s.level).max().unwrap_or(0);
    if top >= 2 {
        let level = (2 + rng.below(3) as u8).min(top);
        opts.push((PlaceReq::Settlement { level }, 4));
    }
    // A remembered spot: the newest public thing the DM decided on a hex (a duel, an encounter, a shrine, a landing).
    let spot = w
        .dm
        .memory
        .iter()
        .rev()
        .filter(|e| e.public && e.beat <= beat && e.scope == Scope::Cell)
        .filter(|e| matches!(e.kind.as_str(), "encounter.revealed" | "duel.end" | "shrine.built" | "summoned" | "loot.dropped"))
        .find_map(|e| {
            let at: LonLat = serde_json::from_value(e.data.get("at").cloned().or_else(|| e.data.pointer("/to/pos").cloned())?).ok()?;
            let place = fn7_society::geo::place_at(w, at);
            let what = match e.kind.as_str() {
                "encounter.revealed" => "the hex near {} where something was uncovered",
                "duel.end" => "the ground near {} where a duel ended",
                "shrine.built" => "the hex near {} where a shrine went up",
                "summoned" => "the spot near {} where a demigod landed",
                _ => "the hex near {} where something was dropped",
            };
            Some(PlaceReq::Point { at, name: what.replace("{}", &w.name_of(Ref::Place(place))) })
        });
    if let Some(p) = spot {
        opts.push((p, 3));
    }
    let _ = anchor;
    // Never a place a doer already stands at (a quest is something to go and do), unless nothing else is left.
    let fresh: Vec<(PlaceReq, u32)> =
        opts.iter().filter(|(r, _)| !standing.iter().any(|d| place_ok(w, r, w.demigods[d.ix()].pos))).cloned().collect();
    let opts = if fresh.is_empty() { opts } else { fresh };
    let total: u32 = opts.iter().map(|x| x.1).sum();
    let mut r = rng.below(total as u64) as u32;
    for (o, wgt) in opts {
        if r < wgt {
            return o;
        }
        r -= wgt;
    }
    PlaceReq::Coast
}

/// Remember a quest fact at the place of the demigod it is for (public when the quest is; else kept for its seat).
pub fn note(w: &mut World, beat: u32, q: &Quest, kind: &'static str, text: String, extra: Value) -> u32 {
    let pos = w.demigods[q.demigod.ix()].pos;
    let wh = dm::locate(w, pos, HexLevel::People);
    let mut data = json!({
        "quest": qref(q.id), "goal": q.goal.kind(), "demigod": Ref::Demigod(q.demigod),
        "name": w.name_of(Ref::Demigod(q.demigod)), "seat": q.seat, "seats": seats_of(q, None),
        "god": w.name_of(Ref::God(q.god)), "at": pos, "cell": wh.cell, "beat": beat,
    });
    if let (Some(o), Value::Object(x)) = (data.as_object_mut(), extra) {
        o.extend(x);
    }
    dm::remember(w, beat, &wh, Decision { scope: Scope::Cell, kind, query: None, public: q.public, text, data })
}

/// The seats a quest's private events go to.
pub fn seats_of(q: &Quest, owner: Option<u8>) -> Vec<u8> {
    let mut v = vec![q.seat];
    v.extend(q.helpers.iter().copied());
    v.extend(owner);
    v.sort();
    v.dedup();
    v
}

pub fn steps_json(q: &Quest) -> Vec<Value> {
    q.steps
        .iter()
        .enumerate()
        .map(|(i, s)| {
            let mut v = json!(s.kind);
            v["step"] = (i + 1).into();
            v["text"] = s.text.clone().into();
            v["done"] = s.done_beat.is_some().into();
            v["done_beat"] = json!(s.done_beat);
            if !s.progress.is_empty() && s.done_beat.is_none() {
                v["progress"] = s.progress.clone().into();
            }
            v
        })
        .collect()
}

/// A quest for payloads: `{ref, for, for_name, seat, goal, god, text, steps[], status, given_beat, expires_beat,
/// done_beat, failed, public}`.
pub fn quest_json(w: &World, q: &Quest) -> Value {
    json!({
        "ref": qref(q.id), "for": Ref::Demigod(q.demigod), "for_name": w.name_of(Ref::Demigod(q.demigod)),
        "seat": q.seat, "helpers": q.helpers, "goal": q.goal, "god": w.name_of(Ref::God(q.god)), "text": q.text,
        "steps": steps_json(q), "steps_done": q.steps.iter().filter(|s| s.done_beat.is_some()).count(),
        "status": q.status(), "given_beat": q.given_beat, "expires_beat": q.expires_beat, "done_beat": q.done_beat,
        "failed": q.failed, "failed_beat": q.failed_beat, "public": q.public,
        "waiting": (!q.waiting.is_empty()).then(|| q.waiting.clone()),
    })
}

/// The standing demigods who may do a quest's steps: its seat's and its helpers'.
pub fn doers(w: &World, q: &Quest) -> Vec<DemigodId> {
    w.demigods.iter().filter(|d| d.alive && q.takes(d.seat)).map(|d| d.id).collect()
}

/// The held item of `d` whose name carries `word`.
pub fn held_with(w: &World, d: DemigodId, word: &str) -> Option<ItemId> {
    let me = Ref::Demigod(d);
    let word = word.to_lowercase();
    w.items
        .iter()
        .find(|i| i.holders.last() == Some(&me) && i.ext.state != ItemState::Destroyed && i.name.to_lowercase().contains(&word))
        .map(|i| i.id)
}

/// The ingredient an open quest of `seat` is waiting on (its current step holds or burns it), if any.
pub fn wanted(b: &Book, seat: u8) -> Vec<(u32, String)> {
    let mut out = vec![];
    for q in b.quests.iter().filter(|q| q.open() && q.takes(seat)) {
        for s in q.steps.iter().filter(|s| s.done_beat.is_none()) {
            match &s.kind {
                StepKind::Hold { word } => out.push((q.id, word.clone())),
                StepKind::At { offer: Some(word), .. } => out.push((q.id, word.clone())),
                _ => {}
            }
        }
    }
    out
}

/// The full name of an ingredient item for `word` ("Butterfly Wings").
pub fn ingredient_name(word: &str) -> String {
    match word {
        "butterfly" => "Butterfly Wings",
        "platinum" => "Stone Washed in Platinum Dust",
        "feather" => "Heron's Feather",
        "salt" => "Salt of a Dried Sea",
        "candle" => "Whale-Tallow Candle",
        "ash" => "Ash of a Struck Oak",
        "fog" => "Jar of Dawn Fog",
        "bell" => "Bell Without a Tongue",
        "glass" => "River Glass",
        "thread" => "Thread from a General's Banner",
        _ => "Odd Ingredient",
    }
    .to_string()
}

fn burn(w: &mut World, item: ItemId, beat: u32) {
    let it = &mut w.items[item.ix()];
    let holder = it.holders.last().copied();
    it.ext.state = ItemState::Destroyed;
    it.ext.history.push(ItemEvent { beat, state: ItemState::Destroyed, holder, by: holder, row: None, count: Some(0.0) });
    event("item_state", Some(Ref::Item(item).to_string()), json!({ "beat": beat, "item": item, "state": "destroyed", "why": "burned for a quest" }));
}

/// Check one step now. `Ok(what happened)` when it is done (side effects applied: an offering burned), else
/// `Err(why not yet)`.
fn check(w: &mut World, q: &Quest, s: &Step, beat: u32, st: &Settings) -> Result<String, String> {
    let who = doers(w, q);
    let phase_now = dm::phase_of(beat, st.beats_per_day).1;
    match &s.kind {
        StepKind::At { req, phase, offer } => {
            if who.is_empty() {
                return Err("nobody of yours stands to go there".into());
            }
            let there: Vec<DemigodId> = who.iter().copied().filter(|d| place_ok(w, req, w.demigods[d.ix()].pos)).collect();
            if there.is_empty() {
                return Err("none of your demigods stands there yet".into());
            }
            if let Some(p) = phase {
                if p != phase_now {
                    return Err(format!("you stand there, but it is {phase_now}, not {p}"));
                }
            }
            match offer {
                Some(word) => match there.iter().find_map(|d| held_with(w, *d, word).map(|i| (*d, i))) {
                    Some((d, item)) => {
                        let name = w.name_of(Ref::Item(item));
                        burn(w, item, beat);
                        Ok(format!("{} burned the {name} there", w.name_of(Ref::Demigod(d))))
                    }
                    None => Err(format!("you stand there, but hold no {word} item to burn")),
                },
                None => Ok(format!("{} stood there", w.name_of(Ref::Demigod(there[0])))),
            }
        }
        StepKind::Hold { word } => match who.iter().find_map(|d| held_with(w, *d, word).map(|i| (*d, i))) {
            Some((d, i)) => Ok(format!("{} holds the {}", w.name_of(Ref::Demigod(d)), w.name_of(Ref::Item(i)))),
            None => Err(format!("nobody of yours holds a {word} item yet")),
        },
        StepKind::Encounter => {
            let won = w.dm.encounters.iter().find(|e| e.outcome.as_ref().is_some_and(|o| o.beat >= q.since && who.contains(&o.by) && o.roll.verdict.ok()));
            match won {
                Some(e) => Ok(e.outcome.as_ref().map(|o| o.text.clone()).unwrap_or_default()),
                None => Err("no encounter won since the quest was given".into()),
            }
        }
        StepKind::Shrine => match w.dm.shrines.iter().find(|x| x.built_beat >= q.since && who.contains(&x.demigod)) {
            Some(x) => Ok(format!("{} was raised", x.name)),
            None => Err("no new shrine raised yet".into()),
        },
        StepKind::Duel => {
            let ok = who.iter().find(|d| w.dm.story(**d).is_some_and(|s| s.tales.iter().any(|t| t.kind == "duel" && t.beat >= q.since)));
            match ok {
                Some(d) => Ok(format!("{} walked away from a duel", w.name_of(Ref::Demigod(*d)))),
                None => Err("no duel survived yet".into()),
            }
        }
        // Paid by a will ([`offer_sparks`] marks it done).
        StepKind::Sparks { n } => Err(format!("{n} sparks not offered yet")),
        StepKind::Army { at, name, .. } => {
            let km = ARMY_KM * scale(w);
            let near = fn7_society::armies(w).find(|(_, a)| !a.rogue && w.demigods.get(a.demigod.ix()).is_some_and(|d| q.takes(d.seat)) && distance_km(a.pos, *at) <= km);
            match near {
                Some((c, _)) => Ok(format!("{} stands in sight of {name}", c.label)),
                None => Err(format!("no army of yours within {km:.0} km of {name}")),
            }
        }
        StepKind::Vigil { phase, times, seen } => {
            if seen >= times {
                Ok(format!("the {phase} came"))
            } else {
                Err(format!("it is {phase_now}; {phase} has come {seen} of {times} times"))
            }
        }
    }
}

/// Offer sparks to the first open quest of `seat` whose current step asks for them (a will's "offer the sparks").
/// `Ok((quest, sparks paid))`, else why not.
pub fn offer_sparks(w: &mut World, book: &mut Book, seat: u8, payer: DemigodId, beat: u32, st: &Settings) -> Result<(u32, u32), String> {
    let Some(qi) = book.quests.iter().position(|q| q.open() && q.takes(seat) && q.current().is_some_and(|c| matches!(q.steps[c].kind, StepKind::Sparks { .. }))) else {
        return Err(match book.quests.iter().find(|q| q.open() && q.takes(seat)) {
            Some(q) => format!("quest {} is not asking for sparks now: {}", qref(q.id), q.current().map(|c| q.steps[c].text.clone()).unwrap_or_default()),
            None => "you have no open quest to offer to".into(),
        });
    };
    let c = book.quests[qi].current().unwrap_or(0);
    let StepKind::Sparks { n } = book.quests[qi].steps[c].kind else { return Err("not a spark step".into()) };
    // Nothing is taken unless the whole offering can be made.
    let paid = super::pay(w, payer, n, true, st);
    if paid.short > 0 {
        return Err(format!("the offering is {n} sparks and the purse holds {} sparks and {} bolts", w.demigods[payer.ix()].sparks, w.demigods[payer.ix()].bolts));
    }
    let q = &mut book.quests[qi];
    q.steps[c].done_beat = Some(beat);
    q.steps[c].progress.clear();
    q.since = beat + 1;
    let q = q.clone();
    event("quest_step", Some(format!("seat:{seat}")), json!({ "beat": beat, "quest": q.id, "step": c + 1, "how": format!("{n} sparks offered") }));
    note(w, beat, &q, "quest.step", format!("Step {} of {} done for {}: {n} sparks offered", c + 1, q.steps.len(), w.name_of(Ref::Demigod(q.demigod))),
         json!({ "step": c + 1, "steps": steps_json(&q), "how": format!("{n} sparks offered") }));
    Ok((q.id, n))
}

/// The beat's quest step (after the DM's step): curses fade, moot and expired quests close, steps are checked in
/// order against what happened, and a finished quest applies its effect.
pub fn step(w: &mut World, beat: u32, pantheon: &Pantheon, st: &Settings) {
    if !st.wills_enabled {
        return;
    }
    let mut book = super::book(w);
    if book.quests.is_empty() && book.curses.is_empty() && book.boons.is_empty() {
        return;
    }
    let before = book.clone();
    // Curses whose time ran out fade.
    for i in 0..book.curses.len() {
        let c = &book.curses[i];
        if c.broken_beat.is_none() && c.until_beat.is_some_and(|u| beat > u) {
            let c = {
                let c = &mut book.curses[i];
                c.broken_beat = Some(beat);
                c.broken_how = "faded".into();
                c.clone()
            };
            super::remember_curse(w, beat, &c, "curse.broken", format!("{} fades from {}: its time ran out", cap(c.kind.title()), w.name_of(Ref::Demigod(c.target))), true);
        }
    }
    book.boons.retain(|b| b.until_beat >= beat);
    // An encounter won this beat drops the ingredient a quest is waiting on.
    let winners: Vec<DemigodId> = w.dm.encounters.iter().filter_map(|e| e.outcome.as_ref()).filter(|o| o.beat == beat && o.roll.verdict.ok()).map(|o| o.by).collect();
    for d in winners {
        let seat = w.demigods[d.ix()].seat;
        if let Some((_, word)) = wanted(&book, seat).into_iter().find(|(_, word)| held_with(w, d, word).is_none()) {
            super::save(w, &book);
            super::make_ingredient(w, beat, d, &word, "found among what the encounter left behind", pantheon, st);
            book = merge_back(w, book);
        }
    }
    for qi in 0..book.quests.len() {
        if !book.quests[qi].open() {
            continue;
        }
        // Moot: what it was for no longer applies.
        let q = &book.quests[qi];
        let target = &w.demigods[q.demigod.ix()];
        let moot = match &q.goal {
            Goal::BreakCurse { curse, .. } => book.curses.iter().find(|c| c.id == *curse).is_none_or(|c| c.broken_beat.is_some()).then_some("the curse is gone"),
            Goal::Raise { .. } => target.alive.then_some("it already stands"),
            Goal::Heal { .. } | Goal::Boon { .. } | Goal::Temper { .. } | Goal::Arm { .. } => (!target.alive).then_some("the one it was for has fallen"),
        };
        let expired = q.expires_beat.is_some_and(|e| beat > e);
        if moot.is_some() || expired {
            let why = moot.unwrap_or("its time ran out");
            let q = {
                let q = &mut book.quests[qi];
                q.failed = Some(if moot.is_some() { "moot".into() } else { "expired".into() });
                q.failed_beat = Some(beat);
                q.clone()
            };
            event("quest_failed", Some(format!("seat:{}", q.seat)), json!({ "beat": beat, "quest": q.id, "why": why }));
            note(w, beat, &q, "quest.failed", format!("The quest for {} lapses: {why}", w.name_of(Ref::Demigod(q.demigod))), json!({ "why": why }));
            continue;
        }
        // A vigil counts each coming of its hour once (the first beat of that phase), after the step began.
        if let Some(c) = book.quests[qi].current() {
            let since = book.quests[qi].since;
            if let StepKind::Vigil { phase, seen, .. } = &mut book.quests[qi].steps[c].kind {
                let now = dm::phase_of(beat, st.beats_per_day).1;
                let before = dm::phase_of(beat.saturating_sub(1).max(1), st.beats_per_day).1;
                if beat > since && now == phase.as_str() && (before != now || beat == 1) {
                    *seen += 1;
                }
            }
        }
        // Steps, in order; several may fall in one beat.
        while let Some(c) = book.quests[qi].current() {
            let q = book.quests[qi].clone();
            match check(w, &q, &q.steps[c], beat, st) {
                Ok(how) => {
                    let q = {
                        let q = &mut book.quests[qi];
                        q.steps[c].done_beat = Some(beat);
                        q.steps[c].progress.clear();
                        q.since = beat + 1;
                        q.clone()
                    };
                    event("quest_step", Some(format!("seat:{}", q.seat)), json!({ "beat": beat, "quest": q.id, "step": c + 1, "how": how }));
                    note(w, beat, &q, "quest.step", format!("Step {} of {} done for {}: {how}", c + 1, q.steps.len(), w.name_of(Ref::Demigod(q.demigod))),
                         json!({ "step": c + 1, "steps": steps_json(&q), "how": how }));
                }
                Err(why) => {
                    book.quests[qi].steps[c].progress = why;
                    break;
                }
            }
        }
        if book.quests[qi].current().is_none() {
            book = complete(w, book, qi, beat, pantheon, st);
        }
    }
    if book != before || super::book(w) != book {
        super::save(w, &book);
    }
}

fn cap(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        Some(f) => f.to_uppercase().chain(c).collect(),
        None => String::new(),
    }
}

/// After something ran a merge (which may spend an item power in the stored book): keep our changes, take its
/// spent powers.
fn merge_back(w: &World, mut book: Book) -> Book {
    let stored = super::book(w);
    for u in stored.used {
        if !book.used.iter().any(|x| x.item == u.item) {
            book.used.push(u);
        }
    }
    book
}

/// A quest whose steps are all done applies its effect (`quest.done`). A raising waits while a seal holds.
fn complete(w: &mut World, mut book: Book, qi: usize, beat: u32, pantheon: &Pantheon, st: &Settings) -> Book {
    let q = book.quests[qi].clone();
    let who = w.name_of(Ref::Demigod(q.demigod));
    let me = Ref::Demigod(q.demigod);
    let result: String = match &q.goal {
        Goal::Heal { amount } => {
            let before = w.demigods[q.demigod.ix()].health;
            super::save(w, &book);
            let p = Proposal {
                source: Source::God { god: q.god, ruling: None },
                intent: None,
                effect: Effect::Heal { who: me, amount: *amount },
                act: format!("The quest is done: {} completes the mending of {who}", w.name_of(Ref::God(q.god))),
                actor: Ref::God(q.god),
                magnitude: 3,
                valence: 2,
                witnesses: vec![me],
                cause: None,
            };
            crate::merge::run(w, vec![p], pantheon, beat, st.max_witnesses as usize);
            book = merge_back(w, book);
            format!("healed {}", r1(w.demigods[q.demigod.ix()].health - before))
        }
        Goal::Boon { bonus, beats } => {
            book.boons.push(super::Boon { demigod: q.demigod, bonus: *bonus, until_beat: beat + *beats, from: format!("quest {}", qref(q.id)) });
            format!("a boon of {bonus:+} on its d20s for {beats} beats")
        }
        Goal::Temper { item, intent, tier } => {
            let found = item.or_else(|| {
                w.manifests.iter().rev().find(|m| m.intent.map(|i| i.0) == Some(*intent) && m.demigod == q.demigod).and_then(|m| m.item)
            });
            match found.filter(|i| w.items[i.ix()].ext.state == ItemState::Held) {
                Some(i) => {
                    let it = &mut w.items[i.ix()];
                    it.ext.tier = *tier;
                    let holder = it.holders.last().copied();
                    it.ext.history.push(ItemEvent { beat, state: ItemState::Held, holder, by: None, row: None, count: Some(it.ext.count) });
                    let it = &w.items[i.ix()];
                    let does = super::arms::arm_of(w, it, Some(pantheon)).map(|a| super::arms::describe(w, &a, false)).unwrap_or_default();
                    format!("the {} is tempered to {} tier: {does}", it.name, tier.as_str())
                }
                None => "the gear it was for is gone".into(),
            }
        }
        Goal::Arm { slot, tier, name, god } => {
            super::save(w, &book);
            let kind = match slot.as_str() {
                "armor" => ItemKind::Armor,
                "charm" => ItemKind::Relic,
                _ => ItemKind::Weapon,
            };
            let made = super::forge_now(w, beat, q.demigod, kind, *tier, name, *god, &format!("quest {}", qref(q.id)), pantheon, st);
            book = merge_back(w, book);
            match made {
                Some(i) => {
                    let it = &w.items[i.ix()];
                    let does = super::arms::arm_of(w, it, Some(pantheon)).map(|a| super::arms::describe(w, &a, false)).unwrap_or_default();
                    format!("forged the {}: {does}", it.name)
                }
                None => "nothing could be forged".into(),
            }
        }
        Goal::BreakCurse { curse, .. } => {
            let mut text = "the curse was already gone".to_string();
            if let Some(c) = book.curses.iter_mut().find(|c| c.id == *curse && c.broken_beat.is_none()) {
                c.broken_beat = Some(beat);
                c.broken_how = "countered".into();
                let c = c.clone();
                text = format!("{} on {who} is broken", c.kind.title());
                super::remember_curse(w, beat, &c, "curse.broken", format!("{} lifts from {who}: its counter-quest is done", cap(c.kind.title())), true);
            }
            text
        }
        Goal::Raise { years } => {
            if let Some(c) = super::curses::active(&book, q.demigod, CurseKind::Seal, beat) {
                // The steps are done; the seal still holds. The quest waits (and says why).
                let why = format!("all is done, but {} still lies on {who}: break it (quest {})", c.kind.title(), qref(c.quest));
                book.quests[qi].waiting = why;
                return book;
            }
            super::save(w, &book);
            let ok = super::raise_now(w, beat, q.demigod, None, q.seat, *years, &format!("quest {}", qref(q.id)), pantheon, st);
            book = merge_back(w, super::book(w));
            if ok {
                format!("{who} rises")
            } else {
                format!("{who} could not rise")
            }
        }
    };
    let q = {
        let q = &mut book.quests[qi];
        q.done_beat = Some(beat);
        q.waiting.clear();
        q.clone()
    };
    event("quest_done", Some(format!("seat:{}", q.seat)), json!({ "beat": beat, "quest": q.id, "result": result }));
    note(w, beat, &q, "quest.done", format!("The quest for {who} is done: {result}"), json!({ "result": result, "steps": steps_json(&q) }));
    book
}

fn r1(x: f32) -> f32 {
    (x * 10.0).round() / 10.0
}
